SELECT o.section,o.delivery_mode FROM course_offerings o WHERE o.year=2026 AND o.semester='2' AND o.campus='국제'
          AND EXISTS (SELECT 1 FROM course_offering_categories oc JOIN departments d ON d.department_id=oc.department_id
                      WHERE oc.offering_id=o.offering_id AND d.code='A10627') AND o.course_code='CSE305';

SELECT w.week AS exam_week,b.isbn FROM course_offerings o JOIN syllabi s USING(offering_id)
        JOIN syllabus_weekly_plans w USING(syllabus_id) JOIN syllabus_textbooks b USING(syllabus_id)
        WHERE o.year=2025 AND o.semester='2' AND o.campus='국제' AND o.course_code='CSE302' AND o.section='01' AND w.topic_content LIKE '%중간 시험%' AND b.sequence=1;

SELECT b.title,b.isbn FROM course_offerings o JOIN syllabi s USING(offering_id)
      JOIN syllabus_textbooks b USING(syllabus_id) WHERE ((o.year=2026 AND o.semester='2' AND o.campus='국제' AND o.course_code='CSE497' AND o.section='04') OR (o.year=2026 AND o.semester='2' AND o.campus='국제' AND o.course_code='CSE499' AND o.section='02')) AND NULLIF(TRIM(b.isbn),'') IS NOT NULL
      GROUP BY b.title,b.isbn HAVING COUNT(DISTINCT o.offering_id)=2;

SELECT s.consultation_time FROM course_offerings o JOIN syllabi s USING(offering_id)
      WHERE ((o.year=2026 AND o.semester='2' AND o.campus='국제' AND o.course_code='SWCON425' AND o.section='00') OR (o.year=2026 AND o.semester='2' AND o.campus='국제' AND o.course_code='SWCON321' AND o.section='00')) AND s.consultation_time IS NOT NULL
      GROUP BY s.consultation_time HAVING COUNT(DISTINCT o.offering_id)=2;

SELECT o.section FROM course_offerings o JOIN syllabi s USING(offering_id)
      WHERE ((o.year=2026 AND o.semester='1' AND o.campus='국제' AND o.course_code='SWCON401' AND o.section='03') OR (o.year=2026 AND o.semester='1' AND o.campus='국제' AND o.course_code='SWCON401' AND o.section='05')) AND EXISTS (SELECT 1 FROM json_each(s.teaching_methods_json) j WHERE j.value='개별발표')
      AND NOT EXISTS (SELECT 1 FROM json_each(s.teaching_methods_json) j WHERE j.value='팀별발표');
